import { readFileSync } from "node:fs";

/**
 * Reads the sales tax rates by region from tax-rates.json at the repo root.
 * The library is pure, so the caller loads this and passes it to placeOrder as `deps.taxRates`.
 */
export function loadTaxRates(path = new URL("./tax-rates.json", import.meta.url)) {
  return JSON.parse(readFileSync(path, "utf8"));
}
EOF
cat > src/tax.js <<'EOF'
import { percentOf } from "./money.js";

/** The tax rate for a region from a rates table, zero when the region is untaxed. */
export function taxRate(rates, region) {
  return rates[region] ?? 0;
}

/** Tax on an amount for a region, rounded to the cent. */
export function taxFor(amount, region, rates) {
  return percentOf(amount, taxRate(rates, region));
}
EOF
