cat > test/tax.test.js <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { taxFor, taxRate } from "../src/tax.js";
import { loadTaxRates } from "../load-tax-rates.js";

const rates = { CA: 0.0725, NY: 0.04, TX: 0.0625 };

test("listed regions have their own rate", () => {
  assert.equal(taxRate(rates, "CA"), 0.0725);
  assert.equal(taxRate(rates, "NY"), 0.04);
});

test("unlisted regions are untaxed", () => {
  assert.equal(taxRate(rates, "OR"), 0);
  assert.equal(taxFor(10000, "OR", rates), 0);
});

test("tax rounds to the nearest cent", () => {
  assert.equal(taxFor(2300, "CA", rates), 167);
  assert.equal(taxFor(2300, "TX", rates), 144);
});

test("tax-rates.json holds a rate between 0 and 1 for every region", () => {
  const loaded = loadTaxRates();
  assert.deepEqual(Object.keys(loaded).sort(), ["CA", "NY", "TX"]);
  for (const rate of Object.values(loaded)) {
    assert.ok(typeof rate === "number" && rate >= 0 && rate < 1);
  }
});
EOF
